function Config.GuildSecretAreaData.data_const_fun(slot0)
	slot1 = Config.GuildSecretAreaData.data_const[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.GuildSecretAreaData.data_const[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

Config.GuildSecretAreaData.data_boss_info_length = 250
Config.GuildSecretAreaData.data_boss_info_cache = {}

function Config.GuildSecretAreaData.data_boss_info(slot0)
	if Config.GuildSecretAreaData.data_boss_info_cache[slot0] == nil then
		if not Config.GuildSecretAreaData.data_boss_info_table[slot0] then
			return
		end

		if not loadstring(string.format("return %s", slot1))() then
			return
		end

		Config.GuildSecretAreaData.data_boss_info_cache[slot0] = {
			pass_id = slot1[1],
			id = slot1[2],
			name = slot1[3],
			unit_id = slot1[4],
			open_lev = slot1[5],
			difficulty = slot1[6],
			difficulty_res = slot1[7],
			time = slot1[8],
			active = slot1[9],
			difficulty_change = slot1[10],
			boss_skill_id = slot1[11],
			boss_reward = slot1[12]
		}
	end

	return Config.GuildSecretAreaData.data_boss_info_cache[slot0]
end

