Config.GuildSecretAreaData.data_chapter_reward_length = 250
Config.GuildSecretAreaData.data_chapter_reward_cache = {}

function Config.GuildSecretAreaData.data_chapter_reward(slot0)
	if Config.GuildSecretAreaData.data_chapter_reward_cache[slot0] == nil then
		if not Config.GuildSecretAreaData.data_chapter_reward_table[slot0] then
			return
		end

		if not loadstring(string.format("return %s", slot1))() then
			return
		end

		Config.GuildSecretAreaData.data_chapter_reward_cache[slot0] = {
			id = slot1[1],
			harm_times = slot1[2],
			max_times = slot1[3],
			change_reward = slot1[4],
			marketplace_rand_reward = slot1[5],
			marketplace_reward = slot1[6]
		}
	end

	return Config.GuildSecretAreaData.data_chapter_reward_cache[slot0]
end

